def cell(value: str) -> str:
    return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("|", "\\|").replace("\n", "<br>")


def sheet_line(row: Row) -> str:
    return "| " + " | ".join(cell(value) for value in
        (row.id, row.feature, row.where, row.action, row.expected, row.settings, f"{row.fixture}: {row.case}")) + " |"


@pytest.fixture(scope="session")
def fixture_runs(tmp_path_factory, request):
    """Batch each fixture file once; every row has its own pytest assertion/result."""
    grouped = defaultdict(list)
    selected = [item.callspec.params["row"] for item in request.session.items
                if item.path == Path(__file__) and hasattr(item, "callspec") and "row" in item.callspec.params]
    for row in selected:
        grouped[row.fixture].append(row.case)
    scratch = tmp_path_factory.mktemp("cli-acceptance")
    # Dependency installation is a setup step, not a test-time network fallback.
    assert (ROOT / "cli/node_modules/csv-parse/package.json").is_file(), "Run npm ci --prefix cli before acceptance tests"
    allowed = {"PATH", "HOME", "TMPDIR", "TEMP", "TMP", "SystemRoot", "SYSTEMROOT", "PATHEXT", "APPDATA", "LOCALAPPDATA", "CI"}
    env = {key: value for key, value in os.environ.items() if key in allowed}
    env.update({"TMPDIR": str(scratch), "TEMP": str(scratch), "TMP": str(scratch),
                "TERVORY_NO_UPDATE_CHECK": "1", "npm_config_offline": "true",
                "COMMAND_TEST_TOOLS": str(ROOT / "cli/node_modules"),
                "NODE_OPTIONS": "--import=" + (ROOT / "tests/acceptance/cli_offline.mjs").as_uri()})
    results = {}
    for fixture, names in grouped.items():
        if fixture.endswith(".py"):
            database = os.environ.get("POOL_SCHEMA_DATABASE_URL", "")
            parsed = urlsplit(database)
            assert parsed.hostname in {"127.0.0.1", "localhost", "::1"} and "test" in parsed.path, "Disposable loopback POOL_SCHEMA_DATABASE_URL is required"
            backend_env = {**env, "POOL_SCHEMA_DATABASE_URL": database,
                           "PYTHONPATH": os.environ.get("PYTHONPATH", str(ROOT / "tank") + os.pathsep + str(ROOT / "tests"))}
            junit = scratch / "plugin-results.xml"
            run = subprocess.run([sys.executable, "-m", "pytest", "-q",
                                  *[fixture + "::" + name for name in names],
                                  "--disable-socket", "--allow-unix-socket", "--allow-hosts=127.0.0.1,localhost,::1",
                                  "--junitxml=" + str(junit)], cwd=ROOT, env=backend_env, text=True, capture_output=True, timeout=180, check=False)
            results[fixture] = (run, junit)
            continue
        pattern = "^(?:" + "|".join(re.escape(name) for name in names) + ")$"
        run = subprocess.run(["node", "--expose-gc", "--test", "--test-reporter=tap",
                              "--test-name-pattern=" + pattern, str(ROOT / fixture)],
                             cwd=ROOT, env=env, text=True, capture_output=True, timeout=180, check=False)
        results[fixture] = (run, None)
    return results


@pytest.mark.parametrize("row", ROWS, ids=lambda row: row.id + "-" + row.feature)
def test_cli_acceptance_row(row: Row, fixture_runs) -> None:
    """The row must match the sheet and execute its named production-path proof."""
    sheet = (ROOT / "docs/acceptance/cli.md").read_text()
    assert sheet.count("| " + row.id + " |") == 1, row.id
    assert sheet_line(row) in sheet, f"Worksheet drift: {row.id}"
    run, junit = fixture_runs[row.fixture]
    assert run.returncode == 0, f"{row.id}: {run.stdout}\n{run.stderr}"
    if junit is not None:
        cases = [case for case in ET.parse(junit).iter("testcase") if case.get("name") == row.case]
        assert len(cases) == 1, f"Named backend proof did not execute: {row.case}"
        assert not any(cases[0].find(tag) is not None for tag in ("failure", "error", "skipped")), f"Unproved backend row: {row.id}"
        return
    tap = run.stdout.replace(r"\#", "#")
    match = re.search(r"^(ok|not ok) \d+ - " + re.escape(row.case) + r"(?P<flags>[^\n]*)$", tap, re.M)
    assert match, f"Named proof did not execute: {row.case}\n{run.stdout}"
    assert match.group(1) == "ok", run.stdout
    assert not re.search(r"#\s*(SKIP|TODO)", match.group("flags"), re.I), f"Unproved row: {row.id}\n{run.stdout}"
